"use client";

import Link from "next/link";
import { Suspense, useActionState } from "react";
import { useSearchParams } from "next/navigation";
import { CheckCircle2 } from "lucide-react";
import { requestPasswordReset, resetPassword } from "@/app/actions/password";
import { keepFormOnSubmit } from "@/lib/use-keep-form";

export function ForgotPasswordForm() {
  const [state, action, pending] = useActionState(requestPasswordReset, undefined);
  if (state?.ok) {
    return (
      <div className="animate-scale-in space-y-3 text-center">
        <CheckCircle2 className="mx-auto h-10 w-10 text-success" aria-hidden />
        <p className="text-sm">If an account exists for that email, we’ve sent a reset link. It’s valid for 30 minutes — check your spam folder too.</p>
        <Link href="/login" className="btn-outline press">Back to sign in</Link>
      </div>
    );
  }
  return (
    <form action={action} onSubmit={keepFormOnSubmit(action)} className="space-y-4">
      <div>
        <label className="label" htmlFor="email">Email</label>
        <input id="email" name="email" type="email" autoComplete="email" required className="input" />
        {state?.fieldErrors?.email && <p className="mt-1 text-xs text-danger">{state.fieldErrors.email[0]}</p>}
      </div>
      {state?.error && <p role="alert" className="rounded-md bg-danger/10 p-3 text-sm text-danger">{state.error}</p>}
      <button disabled={pending} className="btn-brass press w-full py-3">{pending ? "Sending…" : "Send reset link"}</button>
    </form>
  );
}

function TokenInput() {
  return <input type="hidden" name="token" value={useSearchParams().get("token") ?? ""} />;
}

export function ResetPasswordForm() {
  const [state, action, pending] = useActionState(resetPassword, undefined);
  if (state?.ok) {
    return (
      <div className="animate-scale-in space-y-3 text-center">
        <CheckCircle2 className="mx-auto h-10 w-10 text-success" aria-hidden />
        <p className="text-sm">Your password has been changed and you’re signed in. Other devices have been signed out.</p>
        <Link href="/account" className="btn-primary press">Go to my account</Link>
      </div>
    );
  }
  return (
    <form action={action} onSubmit={keepFormOnSubmit(action)} className="space-y-4">
      <Suspense fallback={null}><TokenInput /></Suspense>
      <div>
        <label className="label" htmlFor="password">New password</label>
        <input id="password" name="password" type="password" autoComplete="new-password" required minLength={8} className="input" />
        {state?.fieldErrors?.password && <p className="mt-1 text-xs text-danger">{state.fieldErrors.password[0]}</p>}
      </div>
      {state?.error && <p role="alert" className="rounded-md bg-danger/10 p-3 text-sm text-danger">{state.error} <Link href="/forgot-password" className="font-semibold underline">Request a new link</Link></p>}
      <button disabled={pending} className="btn-brass press w-full py-3">{pending ? "Saving…" : "Set new password"}</button>
    </form>
  );
}
